package org.sonatype.nexus.repository.openformats.swift;
@org.springframework.stereotype.Component @org.springframework.context.annotation.Scope("prototype") @org.springframework.beans.factory.annotation.Qualifier("swift") public class SwiftContent extends org.sonatype.nexus.repository.openformats.OpenContentFacet { public SwiftContent(@org.springframework.beans.factory.annotation.Qualifier("swift") org.sonatype.nexus.repository.content.store.FormatStoreManager store) { super(store); } @Override protected String determineContentType(org.sonatype.nexus.repository.content.Asset asset,org.sonatype.nexus.blobstore.api.Blob blob,boolean strict) { return ("SWIFT_MANIFEST".equals(asset.kind())||asset.path().endsWith(".swift"))?"text/x-swift":super.determineContentType(asset,blob,strict); } }
